}$q$, $q${"type": "object", "required": ["transfer_score", "score_label", "what_worked", "what_missing", "quote"], "properties": {"transfer_score": {"type": "integer", "minimum": 0, "maximum": 2}, "score_label": {"type": "string"}, "what_worked": {"type": "string"}, "what_missing": {"type": "string"}, "quote": {"type": "string"}}}$q$::jsonb)
